INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('9c97ba65-f8f7-445a-a154-e18f8ef36230', '54207e66-e119-4309-ac93-5d4c4e349ffb', 'Sobre as competências atribuídas ao TCU pela Constituição Federal de 1988, assinale a alternativa que NÃO representa uma atribuição constitucional do órgão.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Lajeado - RS / Controlador Interno / Questão: 37', 'O art. 71, I, da CF é claro ao afirmar que compete ao TCU apreciar as contas prestadas anualmente pelo Presidente da República, mediante parecer prévio — quem efetivamente julga essas contas é o Congresso Nacional, por força do art. 49, IX, da CF. Trata-se de distinção clássica e recorrente em provas: o TCU auxilia com um parecer técnico, mas o julgamento político-final é atribuição exclusiva do Legislativo. Por isso, a alternativa "a" está incorreta ao atribuir ao TCU o poder de "julgar" essas contas. As demais alternativas correspondem, respectivamente, ao art. 71, III (b), art. 71, XI (c), art. 71, X (d) e art. 71, IX (e), todas competências efetivamente constitucionais do TCU.', 1, true),
('0917b2eb-fb27-45cb-b2f3-a2652cf70882', '54207e66-e119-4309-ac93-5d4c4e349ffb', 'Em matéria de responsabilização, "se o TCU condena um gestor a devolver recursos ao Tesouro Nacional, e se isso não ocorrer no prazo determinado, o Tribunal encaminha a decisão para a Advocacia-Geral da União, que entra com um processo de execução para reaver os valores" (TCU, 2024). Neste sentido, segundo o artigo 71, § 3º da Constituição Federal, as decisões do Tribunal de Contas da União (TCU) possuem força de título:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de São Vicente do Sul - RS / Auditor Público Interno / Questão: 40', 'O art. 71, § 3º, da CF/88 estabelece que "as decisões do Tribunal de que resulte imputação de débito ou multa terão eficácia de título executivo". Essa natureza executiva é justamente o que permite à Advocacia-Geral da União (ou aos entes estaduais/municipais equivalentes) ajuizar diretamente a ação de execução para cobrança forçada dos valores, sem necessidade de novo processo de conhecimento. As demais alternativas descrevem categorias que não correspondem ao texto constitucional nem à natureza jurídica atribuída a essas decisões.', 2, true),
('88e7125e-791e-45d1-b482-edf9de0663c6', '54207e66-e119-4309-ac93-5d4c4e349ffb', 'Consoante a Constituição Federal, a fiscalização do Município será exercida pelo Poder Legislativo Municipal, mediante controle externo, e pelos sistemas de controle interno do Poder Executivo Municipal, na forma da lei, e: I. O controle externo da Câmara Municipal será exercido com o auxílio dos Tribunais de Contas dos Estados ou do Município ou dos Conselhos ou Tribunais de Contas dos Municípios, onde houver.II. O parecer prévio, emitido pelo órgão competente sobre as contas que o Prefeito deve anualmente prestar, só deixará de prevalecer por decisão de dois terços dos membros da Câmara Municipal.III. As contas dos Municípios ficarão, durante sessenta dias, anualmente, à disposição de qualquer contribuinte, para exame e apreciação, o qual poderá questionar-lhes a legitimidade, nos termos da lei. Quais estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Monte Castelo - SC / Procurador / Questão: 18', 'Observação: o item IV citado nas alternativas desta questão não foi capturado integralmente na fonte original (falha comum de digitalização em documentos de duas colunas); a análise a seguir concentra-se nos itens I, II e III efetivamente disponíveis. A assertiva I reproduz o art. 31, § 1º, da CF, estando correta. A assertiva II corresponde ao art. 31, § 2º, que exige quórum qualificado de dois terços dos membros da Câmara Municipal para rejeitar o parecer prévio sobre as contas do Prefeito, estando correta. A assertiva III reproduz o art. 31, § 3º, que garante a qualquer contribuinte o direito de examinar e questionar a legitimidade das contas municipais durante o prazo de 60 dias, estando também correta. Sendo todas as assertivas disponíveis verdadeiras, o gabarito oficial (E) confirma que o item IV (não capturado no texto) também estava correto.', 3, true),
('206fc9ac-eccc-4e7a-836d-76380629e251', '54207e66-e119-4309-ac93-5d4c4e349ffb', 'Conforme a Constituição Federal, os ministros do Tribunal de Contas da União serão nomeados entre brasileiros que satisfaçam os seguintes requisitos:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Arroio do Sal - RS / Eletricista / Questão: 24', 'O art. 73, § 1º, da CF estabelece quatro requisitos cumulativos para a nomeação dos Ministros do TCU: (I) mais de 35 e menos de 65 anos de idade; (II) idoneidade moral e reputação ilibada; (III) notórios conhecimentos jurídicos, contábeis, econômicos e financeiros ou de administração pública; e (IV) mais de dez anos de exercício de função ou de efetiva atividade profissional que exija os conhecimentos mencionados no inciso anterior. As demais alternativas são fantasiosas e não encontram qualquer correspondência no texto constitucional.', 4, true),
('60f01d8c-0dd3-4985-9b75-dae66331b056', '54207e66-e119-4309-ac93-5d4c4e349ffb', 'Relacione a Coluna 1 à Coluna 2, associando os tipos de auditoria às suas respectivas características, conforme previsto na Constituição Federal de 1988. Coluna 11. Auditoria Financeira.2. Auditoria Operacional.3. Auditoria Orçamentária.4. Auditoria Contábil.Coluna 2( ) Está relacionada à verificação do cumprimento de metas, resultados, eficácia e eficiência da gestão dos recursos públicos.( ) Está relacionada à aplicação dos recursos públicos, conforme as leis orçamentárias, acompanhando a arrecadação dos recursos e a aplicação.( ) Consiste na verificação da legalidade e legitimidade na realização das despesas, observando se o gestor público cumpriu os princípios e as regras estabelecidas para as aquisições de bens e serviços e de liquidação da despesa pública.( ) Tem como objetivo verificar se os fatos relacionados com a gestão dos recursos públicos estão sendo escriturados de acordo com as normas contábeis aplicadas ao caso. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Carlos Barbosa - RS / Contador / Questão: 59', 'A base é o art. 70, caput, da CF, que elenca os aspectos da fiscalização (contábil, financeira, orçamentária, operacional e patrimonial). A auditoria operacional (2) verifica cumprimento de metas, eficácia e eficiência da gestão — 1º parêntese. A auditoria orçamentária (3) acompanha a execução da receita e despesa conforme as leis orçamentárias — 2º parêntese. A auditoria financeira (1) verifica a legalidade e legitimidade das despesas, licitações e liquidação — 3º parêntese. Por fim, a auditoria contábil (4) verifica a correta escrituração dos atos de gestão conforme as normas contábeis — 4º parêntese. Daí a sequência correta: 2 – 3 – 1 – 4.', 5, true),
('c500d574-871a-4abc-abde-19c4c89a671f', '54207e66-e119-4309-ac93-5d4c4e349ffb', 'As contas prestadas anualmente pelo Presidente da República e as contas nacionais das empresas supranacionais de cujo capital social a União participe estão sujeitas ao controle externo, que é de competência do(a):', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Câmara de Venâncio Aires - RS / Contador / Questão: 46', 'O art. 70, caput, combinado com o art. 71, caput, da CF, deixa claro que a fiscalização contábil, financeira, orçamentária, operacional e patrimonial da União é exercida pelo Congresso Nacional, mediante controle externo, com o auxílio do Tribunal de Contas da União — o TCU não exerce o controle externo sozinho, mas atua como órgão técnico auxiliar do Legislativo. A alternativa "e", embora tentadora, está incompleta por atribuir a competência apenas ao TCU, ignorando que o titular constitucional do controle externo é o Congresso Nacional.', 6, true),
('8e10fbee-d90d-46c0-80d9-4e4fa31ba8e4', '54207e66-e119-4309-ac93-5d4c4e349ffb', 'A Constituição Federal prevê que a fiscalização contábil, financeira, orçamentária, operacional e patrimonial da União e das entidades da administração direta e indireta, quanto à legalidade, legitimidade, economicidade, aplicação das subvenções e renúncia de receitas, será exercida pelo Congresso Nacional, mediante controle externo, e pelo sistema de controle interno de cada Poder. Nesse contexto, são competências do Tribunal de Contas da União, EXCETO:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Grupo Hospitalar Conceição GHC - RS / Contador / Questão: 30', 'As alternativas "a", "b", "c" e "d" reproduzem fielmente competências do TCU previstas, respectivamente, nos incisos VI, X, I e II do art. 71 da CF — todas, portanto, atribuições efetivamente constitucionais do Tribunal. Como a questão pede a alternativa que NÃO representa competência do TCU, e as quatro primeiras estão corretamente descritas, a resposta correta necessariamente recai sobre a alternativa "e", cujo texto não foi integralmente capturado na extração do documento, mas que, por exclusão lógica, deve trazer uma atribuição estranha ao rol do art. 71 (por exemplo, alguma competência típica de outro órgão, como julgamento de crimes de responsabilidade ou fiscalização atribuída a outro Poder).', 7, true);
INSERT INTO public.questao_alternativas (questao_id, letra, texto, correta, ordem) VALUES
('9c97ba65-f8f7-445a-a154-e18f8ef36230', 'A', 'Julgar as contas prestadas anualmente pelo Presidente da República.', true, 0),
('9c97ba65-f8f7-445a-a154-e18f8ef36230', 'B', 'Apreciar, para fins de registro, a legalidade dos atos de admissão de pessoal, a qualquer título, na administração direta e indireta, incluídas as fundações instituídas e mantidas pelo poder público.', false, 1),
('9c97ba65-f8f7-445a-a154-e18f8ef36230', 'C', 'Representar ao Poder competente sobre irregularidades ou abusos apurados no exercício de suas funções.', false, 2),
('9c97ba65-f8f7-445a-a154-e18f8ef36230', 'D', 'Sustar, se não atendida, a execução do ato impugnado, comunicando a decisão à Câmara dos Deputados e ao Senado Federal.', false, 3),
('9c97ba65-f8f7-445a-a154-e18f8ef36230', 'E', 'Assinar prazo para que o órgão ou entidade adote as providências necessárias ao exato cumprimento da lei, quando verificada ilegalidade.', false, 4),
('0917b2eb-fb27-45cb-b2f3-a2652cf70882', 'A', 'De crédito alienável.', false, 0),
